update events set legs = 2, tiebreak = 'diff_only', ko_target_score = 21, ko_win_by = 1, ko_cap = 21, ko_switch_at = 0,
  ko_from_sf = true, ko_final_only = false, final_best_of = 1, play_clock = true, court_dispatch = 'pool', pool_strict = true,
  bracket_preview = true, tv_partner = 'MCXD', ko_court_plan = '{"KO-8-0":1,"KO-8-1":2,"KO-8-2":3,"KO-8-3":1,"KO-4-0":1,"KO-4-1":1,"KO-3P":1,"KO-2-0":1}'::jsonb
where id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCMD');

update matches m set home_court = c.id, slot = v.slot
from (values (1, 1, 1), (2, 2, 1), (3, 3, 1), (4, 1, 2), (5, 2, 2), (6, 1, 3), (7, 2, 3), (8, 3, 3), (9, 1, 4), (10, 2, 4), (11, 1, 5), (12, 2, 5), (13, 3, 5), (14, 1, 6), (15, 2, 6), (16, 1, 7), (17, 2, 7), (18, 3, 7), (19, 1, 8), (20, 2, 8), (21, 1, 9), (22, 2, 9), (23, 3, 9), (24, 1, 10), (25, 2, 10), (26, 1, 11), (27, 2, 11), (28, 3, 11), (29, 1, 12), (30, 2, 12)) as v(seq, n, slot)
join courts c on c.number = v.n and c.competition_id = (select id from competitions where code = 'MCMD')
where m.event_id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCMD') and m.sequence = v.seq;

update teams t set name = k.name, player1 = k.player1, player2 = k.player2, logo = k.logo
from (select id, row_number() over (order by pool, id) as n from teams where event_id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCMD')) s,
     mc_reg_keep k
where t.id = s.id and s.n = k.n;

